mapper.update:
UPDATE ca_bootstrap_credential
   SET status = 'USED', used_at = #{usedAt}
 WHERE identity_id = #{identityId} AND token_hash = #{tokenHash}
   AND status = 'ACTIVE' AND expires_at >= #{usedAt}

mapper.select:
SELECT id, tenant_id, identity_id, serial_number, certificate_chain, csr_fingerprint,
       idempotency_key, status, not_before, not_after, issued_at
  FROM ca_operational_certificate
 WHERE tenant_id = #{tenantId} AND identity_id = #{identityId}
   AND idempotency_key = #{idempotencyKey}

mapper.update:
UPDATE ca_operational_certificate
   SET status = 'SUPERSEDED', superseded_at = #{supersededAt}
 WHERE tenant_id = #{tenantId} AND identity_id = #{identityId} AND status = 'ACTIVE'

UPDATE ca_operational_certificate
   SET status = 'REVOKED', revoked_at = #{revokedAt}, revoke_reason = #{reason}
 WHERE tenant_id = #{tenantId} AND identity_id = #{identityId} AND status = 'ACTIVE'

UPDATE ca_device_identity
   SET status = #{identity.status}, updated_at = #{identity.updatedAt}, version = version + 1
 WHERE identity_id = #{identity.identityId} AND tenant_id = #{identity.tenantId}
   AND version = #{expectedVersion}
